package dev.konqasasas.beat.spigot;import dev.konqasasas.beat.*;import dev.konqasasas.beat.application.*;import dev.konqasasas.beat.configuration.ConfigurationFiles;import dev.konqasasas.beat.domain.endurance.*;import dev.konqasasas.beat.domain.state.*;import dev.konqasasas.beat.map.*;import dev.konqasasas.beat.map.persistence.*;import dev.konqasasas.beat.map.validation.*;import dev.konqasasas.beat.persistence.*;import dev.konqasasas.beat.roster.*;import dev.konqasasas.beat.ui.DustSphereRenderer;import java.util.*;import java.util.logging.*;import net.md_5.bungee.api.*;import net.md_5.bungee.api.chat.*;import org.bukkit.*;import org.bukkit.boss.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.player.*;import org.bukkit.scheduler.*;import org.bukkit.util.Vector;
import dev.konqasasas.beat.configuration.CompetitionSettingsService;
public final class EnduranceController implements Listener,LiveCompetitionClock{private final BeatPlugin plugin;private final RosterService rosters;private final EventStateService states;private final MapConfigurationService maps;private final MapValidationService validation;private final EnduranceResultService results;private final ConfigurationFiles configuration;private final CompetitionSettingsService settings;private EnduranceSession session;private BukkitTask task;private BossBar bar;private int countdown;private long tick;private long totalTicks;private boolean rankingDirty;private List<Integer> eliminationTicks=List.of();private final Set<Integer> processedEliminations=new HashSet<>();private final Set<UUID> suppressTeleportDetection=new HashSet<>();private final ActionBarFeedbackState feedback=new ActionBarFeedbackState();
public EnduranceController(BeatPlugin p,RosterService r,EventStateService s,MapConfigurationService m,MapValidationService v,EnduranceResultService x,ConfigurationFiles configuration,CompetitionSettingsService settings){plugin=p;rosters=r;states=s;maps=m;validation=v;results=x;this.configuration=configuration;this.settings=settings;}public void start()throws PersistenceException{if(session!=null)throw new IllegalStateException("耐久は進行中です");var state=states.current().tournamentState();if(state!=TournamentState.TA_FINISHED&&state!=TournamentState.ENDURANCE_READY)throw new IllegalStateException("耐久を開始できる状態ではありません");var report=validation.validateEndurance(maps.endurance());if(!report.passed())throw new IllegalStateException("耐久マップ検証ERROR: "+report.errorCount());var schedule=settings.current();totalTicks=schedule.enduranceRunningTicks();eliminationTicks=schedule.enduranceEliminationTicks();processedEliminations.clear();if(state==TournamentState.TA_FINISHED)states.transitionTo(TournamentState.ENDURANCE_READY);states.transitionTo(TournamentState.ENDURANCE_COUNTDOWN);Map<UUID,String> names=new LinkedHashMap<>();rosters.current().participants().forEach((id,x)->names.put(id,states.tournamentName(id).orElse(x.mcid())));var c=maps.endurance();session=new EnduranceSession(names,new EnduranceRules(c.zone2Progress(),c.zone3Progress(),c.goalProgress()));bar=Bukkit.createBossBar(configuration.message("ui.bossbar.endurance-title","ENDURANCE"),configuration.barColor("boss-bars.endurance",BarColor.GREEN),configuration.barStyle("boss-bars.endurance",BarStyle.SOLID));countdown=(int)schedule.startCountdownTicks();tick=0;rankingDirty=true;forPlayers(this::prepare);announce(countdown/20);task=Bukkit.getScheduler().runTaskTimer(plugin,this::run,1,1);}
@EventHandler(priority=EventPriority.HIGHEST)public void move(PlayerMoveEvent e){if(session!=null&&countdown>0&&session.contains(e.getPlayer().getUniqueId())&&e.getTo()!=null){var f=e.getFrom();var t=e.getTo();t.setX(f.getX());t.setY(f.getY());t.setZ(f.getZ());e.setTo(t);}}
@EventHandler public void join(PlayerJoinEvent e){if(session==null||!session.contains(e.getPlayer().getUniqueId()))return;Bukkit.getScheduler().runTask(plugin,()->{Player p=e.getPlayer();if(session.active(p.getUniqueId())){CompetitionPlayerState.normalize(p);bar.addPlayer(p);rankingDirty=true;return;}if(!eliminationTicks.isEmpty()&&tick>=eliminationTicks.getFirst()){p.setGameMode(GameMode.SPECTATOR);rankingDirty=true;return;}session.activate(p.getUniqueId());CompetitionPlayerState.normalize(p);tp(p,maps.endurance().start());bar.addPlayer(p);rankingDirty=true;});}
private void run(){try{if(countdown>0){if(--countdown==0){states.transitionTo(TournamentState.ENDURANCE_RUNNING);forPlayers(p->session.activate(p.getUniqueId()));Bukkit.broadcastMessage(configuration.message("notifications.endurance.started","[BEAT] 耐久競技開始！"));rankingDirty=true;updateRankingIfDirty();}else if(countdown%20==0)announce(countdown/20);return;}long previous=tick++;scan();renderProgressParticles();cutoffs(previous,tick);announceTimeLimit();updateRankingIfDirty();ui();if(tick>=totalTicks)finish();}catch(Exception e){plugin.getLogger().log(Level.SEVERE,"耐久進行を停止しました",e);shutdown();}}
private void scan(){double horizontalRadius=configuration.configDouble("endurance.progress-trigger.horizontal-radius",0.25D,0D,16D);double verticalTolerance=configuration.configDouble("endurance.progress-trigger.vertical-tolerance",0.5D,0D,16D);for(Player p:Bukkit.getOnlinePlayers()){UUID id=p.getUniqueId();if(!session.contains(id)||!session.active(id))continue;if(suppressTeleportDetection.remove(id))continue;MapLocation l=loc(p);int best=0;for(var x:maps.endurance().progresses().entrySet())if(x.getValue().stream().anyMatch(point->point.contains(l,horizontalRadius,verticalTolerance))&&x.getKey()>best)best=x.getKey();if(best>0){var u=session.reach(id,best,tick);if(u.progress().changed()){rankingDirty=true;if(u.goal()){notice(p,configuration.message("notifications.endurance.goal","GOAL! ｜ {time} ｜ #{rank}",Map.of("time",clock(tick),"rank",u.currentRank())));Bukkit.broadcastMessage(configuration.message("notifications.endurance.goal-broadcast","[BEAT] {player} が完走！ {time} (#{rank})",Map.of("player",session.competitor(id).tournamentName(),"time",clock(tick),"rank",u.currentRank())));playConfigured(p,"sounds.endurance-goal",Sound.UI_TOAST_CHALLENGE_COMPLETE,1,1);}else if(u.zone2()||u.zone3()){int z=u.zone3()?3:2;notice(p,configuration.message("notifications.endurance.zone","Zone {zone} 到達 ｜ Progress {progress} ｜ #{rank}",Map.of("zone",z,"progress","%03d".formatted(best),"rank","%02d".formatted(u.currentRank()))));playConfigured(p,"sounds.endurance-zone",Sound.ENTITY_PLAYER_LEVELUP,1,1);}else{notice(p,configuration.message("notifications.endurance.progress","Progress {progress} 到達 ｜ #{rank}",Map.of("progress","%03d".formatted(best),"rank","%02d".formatted(u.currentRank()))));playConfigured(p,"sounds.endurance-progress",Sound.BLOCK_NOTE_BLOCK_PLING,0.7f,1.5f);}if(u.rankChanged()&&!u.goal())Bukkit.broadcastMessage(configuration.message("notifications.endurance.rank-update","[BEAT] {player} が更新: Progress {progress} (#{rank})",Map.of("player",session.competitor(id).tournamentName(),"progress","%03d".formatted(best),"rank",u.currentRank())));}}if(EnduranceFallPolicy.shouldRestart(session.record(id),p.getLocation().getY(),maps.endurance().fallY())){p.setVelocity(new Vector());tp(p,restart(id));suppressTeleportDetection.add(id);}}}
private void renderProgressParticles(){int interval=configuration.styleInt("endurance-progress-particles.interval-ticks",5,1,100);if(tick%interval!=0)return;double distance=configuration.styleDouble("endurance-progress-particles.view-distance",32D,1D);double distanceSquared=distance*distance;int particleLimit=configuration.styleInt("endurance-progress-particles.max-particles-per-player",8000,DustSphereRenderer.PARTICLES_PER_SPHERE,40000);int sphereLimit=Math.max(1,particleLimit/DustSphereRenderer.PARTICLES_PER_SPHERE);var completed=configuration.dustOptions("endurance-progress-particles.completed",Color.fromRGB(70,220,90),0.6F);var next=configuration.dustOptions("endurance-progress-particles.next",Color.fromRGB(255,200,40),0.8F);var future=configuration.dustOptions("endurance-progress-particles.future",Color.fromRGB(40,210,255),0.6F);for(Player player:Bukkit.getOnlinePlayers()){UUID id=player.getUniqueId();if(!session.contains(id)||!session.active(id))continue;int current=session.record(id).maxProgress();Integer nextProgress=maps.endurance().progresses().keySet().stream().filter(number->number>current).min(Integer::compareTo).orElse(null);int emitted=0;Location location=player.getLocation();for(var progress:maps.endurance().progresses().entrySet().stream().sorted(Comparator.<Map.Entry<Integer,List<EnduranceProgressPoint>>>comparingInt(entry->particlePriority(entry.getKey(),current,nextProgress)).thenComparingInt(Map.Entry::getKey)).toList()){var dust=progress.getKey()<=current?completed:Objects.equals(progress.getKey(),nextProgress)?next:future;for(EnduranceProgressPoint point:progress.getValue()){if(emitted>=sphereLimit)break;if(!point.world().equals(location.getWorld().getName()))continue;double dx=point.x()-location.getX(),dy=point.y()-location.getY(),dz=point.z()-location.getZ();if(dx*dx+dy*dy+dz*dz>distanceSquared)continue;DustSphereRenderer.spawn(player,point,dust);emitted++;}if(emitted>=sphereLimit)break;}}}
private static int particlePriority(int progress,int current,Integer next){if(Objects.equals(progress,next))return 0;return progress<=current?1:2;}
private MapLocation restart(UUID id){return switch(session.zone(id)){case 3->maps.endurance().zone3Restart();case 2->maps.endurance().zone2Restart();default->maps.endurance().start();};}
private void cutoffs(long previous,long current){for(int i=0;i<Math.min(2,eliminationTicks.size());i++){long boundary=eliminationTicks.get(i),rem=boundary-current;int zone=i+2;if(rem>=20&&rem<=200&&rem%20==0)forPlayers(p->{p.sendMessage(configuration.message("notifications.endurance.elimination-warning","[BEAT] Zone {zone} 未到達者脱落まで... {seconds}",Map.of("zone",zone,"seconds",rem/20)));playConfigured(p,"sounds.countdown",Sound.BLOCK_NOTE_BLOCK_HAT,1,1);});if(previous<boundary&&current>=boundary&&processedEliminations.add(i)){Bukkit.broadcastMessage(configuration.message("notifications.endurance.elimination","[BEAT] Zone {zone} 未到達者脱落！",Map.of("zone",zone)));forPlayers(p->playConfigured(p,"sounds.elimination",Sound.BLOCK_NOTE_BLOCK_BASS,1,0.7F));var eliminated=session.eliminateWithoutZone(zone);rankingDirty=true;for(var x:eliminated){Player p=Bukkit.getPlayer(x.id());if(p!=null){p.setGameMode(GameMode.SPECTATOR);p.sendMessage(configuration.message("notifications.endurance.eliminated","[BEAT] 脱落しました。最終記録: Progress {progress} (#{rank})",Map.of("progress","%03d".formatted(x.progress()),"rank",x.rank())));}}}}}
private void announceTimeLimit(){long remaining=totalTicks-tick;if(remaining>0&&remaining<=200&&remaining%20==0)forPlayers(p->{p.sendMessage(configuration.message("notifications.endurance.time-limit-countdown","[BEAT] 制限時間終了まで... {seconds}",Map.of("seconds",remaining/20)));playConfigured(p,"sounds.countdown",Sound.BLOCK_NOTE_BLOCK_HAT,1,1);});else if(remaining==0)forPlayers(p->{p.sendMessage(configuration.message("notifications.endurance.time-limit-ended","[BEAT] 制限時間終了！"));playConfigured(p,"sounds.time-limit-end",Sound.BLOCK_NOTE_BLOCK_BASS,1,0.5F);});}
private void ui(){if(tick%configuration.configInt("ui-update-ticks.action-bar",10,1,1200)!=0)return;long total=totalTicks;bar.setProgress(Math.max(0,(double)(total-tick)/total));Long next=eliminationTicks.stream().mapToLong(Integer::longValue).filter(x->x>tick).boxed().findFirst().orElse(null);bar.setTitle(configuration.message("ui.bossbar.competition-time","残り時間 {remaining} ｜ 次の脱落 {next}",Map.of("remaining",clock(total-tick),"next",next==null?"--:--":clock(next-tick))));forPlayers(p->{UUID id=p.getUniqueId();String notification=feedback.activeMessage(id,tick);if(notification!=null){action(p,notification);return;}int progress=session.record(id).maxProgress();String rank=progress==0?"--":"%02d".formatted(session.rank(id));action(p,configuration.message("ui.endurance.status","Progress {progress} ｜ #{rank} ｜ Zone {zone}",Map.of("progress","%03d".formatted(progress),"rank",rank,"zone","%02d".formatted(session.zone(id)))));});}
private void updateRankingIfDirty(){if(!rankingDirty)return;rankingDirty=false;updateRanking();}
private void updateRanking(){var manager=Bukkit.getScoreboardManager();if(manager==null)return;var ranking=session.rankings();forPlayers(v->{var board=manager.getNewScoreboard();var o=board.registerNewObjective("beat_end",org.bukkit.scoreboard.Criteria.DUMMY,configuration.message("ui.scoreboard.endurance-title","ENDURANCE"));o.setDisplaySlot(org.bukkit.scoreboard.DisplaySlot.SIDEBAR);int score=Math.min(10,ranking.size());for(var e:ranking.stream().limit(10).toList())o.getScore(configuration.message("ui.scoreboard.endurance-row","#{rank} Progress {progress} {player}",Map.of("rank","%02d".formatted(e.rank()),"progress","%03d".formatted(e.record().maxProgress()),"player",e.competitor().tournamentName()))).setScore(score--);v.setScoreboard(board);});for(var e:ranking){Player p=Bukkit.getPlayer(e.competitor().uuid());if(p!=null){p.setPlayerListOrder(e.rank());p.setPlayerListName(configuration.message("ui.tab.endurance-row","#{rank} Progress {progress} {player}",Map.of("rank","%02d".formatted(e.rank()),"progress","%03d".formatted(e.record().maxProgress()),"player",p.getName())));}}}
@Override public synchronized Optional<LiveCompetitionClock.Snapshot> liveClock(){return session==null?Optional.empty():Optional.of(new LiveCompetitionClock.Snapshot(countdown>0?"ENDURANCE_COUNTDOWN":"ENDURANCE_RUNNING",countdown>0?settings.current().startCountdownTicks()-countdown:tick,countdown>0?settings.current().startCountdownTicks():totalTicks,countdown>0?List.of(settings.current().startCountdownTicks()):eliminationTicks.stream().map(Integer::longValue).toList()));}
@Override public synchronized void debugSetElapsedTick(long target){if(session==null)throw new IllegalStateException("耐久は進行中ではありません");if(countdown>0){long elapsed=settings.current().startCountdownTicks()-countdown;if(target<elapsed||target>=settings.current().startCountdownTicks())throw new IllegalArgumentException("指定時刻が範囲外です");countdown=(int)(settings.current().startCountdownTicks()-target);return;}if(target<tick||target>=totalTicks)throw new IllegalArgumentException("指定時刻が範囲外です");long previous=tick;tick=target;cutoffs(previous,tick);rankingDirty=true;ui();}
public void forceFinish()throws PersistenceException{if(session==null)throw new IllegalStateException("耐久競技は実行中ではありません");finish();}
private void finish()throws PersistenceException{session.finish();results.saveFinal(session);states.transitionTo(TournamentState.ENDURANCE_FINISHED);forPlayers(p->{p.setGameMode(GameMode.ADVENTURE);p.setVelocity(new Vector());tp(p,maps.endurance().end());});Bukkit.broadcastMessage(configuration.message("notifications.endurance.finished","[BEAT] 耐久が終了し結果を確定しました。"));shutdown();}private void validateTiming(){long total=plugin.getConfig().getLong("timings.endurance-running-ticks",36000);var cuts=plugin.getConfig().getIntegerList("eliminations.endurance-ticks");if(total<1||cuts.size()!=2||cuts.get(0)<=0||cuts.get(1)<=cuts.get(0)||cuts.get(1)>=total)throw new IllegalStateException("耐久の時間設定が不正です");}private void prepare(Player p){CompetitionPlayerState.normalize(p);tp(p,maps.endurance().start());bar.addPlayer(p);}private void announce(int n){forPlayers(p->{p.sendMessage(configuration.message("notifications.endurance.countdown","[BEAT] 競技開始まで... {seconds}",Map.of("seconds",n)));playConfigured(p,"sounds.countdown",Sound.BLOCK_NOTE_BLOCK_HAT,1,1);});}private void playConfigured(Player p,String path,Sound fallback,float volume,float pitch){p.playSound(p.getLocation(),configuration.sound(path,fallback),configuration.soundVolume(path,volume),configuration.soundPitch(path,pitch));}private void forPlayers(java.util.function.Consumer<Player> c){for(Player p:Bukkit.getOnlinePlayers())if(session!=null&&session.contains(p.getUniqueId()))c.accept(p);}public void shutdown(){if(task!=null)task.cancel();task=null;if(bar!=null)bar.removeAll();bar=null;if(session!=null)forPlayers(p->{CompetitionPlayerState.release(p);p.setPlayerListOrder(0);p.setPlayerListName(p.getName());var m=Bukkit.getScoreboardManager();if(m!=null)p.setScoreboard(m.getMainScoreboard());});session=null;suppressTeleportDetection.clear();feedback.clear();}private void notice(Player p,String s){String notification=configuration.actionBarNotification(s);feedback.show(p.getUniqueId(),notification,tick+configuration.styleInt("display-ticks.feedback",20,1,1200));action(p,notification);}private static void action(Player p,String s){p.spigot().sendMessage(ChatMessageType.ACTION_BAR,TextComponent.fromLegacy(s));}private static String clock(long ticks){long s=Math.max(0,(ticks+19)/20);return "%02d:%02d".formatted(s/60,s%60);}private static MapLocation loc(Player p){var l=p.getLocation();return new MapLocation(l.getWorld().getName(),l.getX(),l.getY(),l.getZ(),l.getYaw(),l.getPitch());}private static void tp(Player p,MapLocation l){World w=Bukkit.getWorld(l.world());if(w!=null)p.teleport(new Location(w,l.x(),l.y(),l.z(),l.yaw(),l.pitch()));}}
